// TEMP — verify dotted vs hoisted method calls with the loop INSIDE the
// timed region (no per-op closure), median of runs.
import { describe, it } from 'vitest';
import { ref } from 'vue';
import { Reactive } from '../Reactive';

class $Box {
  get width() {
    return ref(1);
  }
  grow() {
    return this.width.value + 1;
  }
}
const Box = Reactive($Box);

function median(values: number[]) {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.floor(sorted.length / 2)];
}

function run(label: string, fn: (iterations: number) => number, iterations = 1_000_000, runs = 9) {
  const times: number[] = [];
  let sum = 0;
  for (let i = 0; i < runs; i++) {
    const t0 = performance.now();
    sum += fn(iterations);
    times.push(performance.now() - t0);
  }
  if (sum < 0) throw new Error('unreachable');
  console.log(`${label}: ${((median(times) * 1e6) / iterations).toFixed(2)} ns/call (1M-call loops)`);
}

describe('hoisted vs dotted method calls', () => {
  it('measures', () => {
    const instance: any = new Box();
    instance.grow(); // materialize + bind

    run('dotted  instance.grow()', (iterations) => {
      let sum = 0;
      for (let i = 0; i < iterations; i++) sum += instance.grow();
      return sum;
    });

    run('hoisted grow()', (iterations) => {
      const grow = instance.grow;
      let sum = 0;
      for (let i = 0; i < iterations; i++) sum += grow();
      return sum;
    });

    const width = instance.width;
    run('hoisted ref, inlined body', (iterations) => {
      let sum = 0;
      for (let i = 0; i < iterations; i++) sum += width.value + 1;
      return sum;
    });

    const closureWidth = ref(1);
    const closureGrow = () => closureWidth.value + 1;
    run('native closure grow()', (iterations) => {
      let sum = 0;
      for (let i = 0; i < iterations; i++) sum += closureGrow();
      return sum;
    });
  }, 300_000);
});
EOF
