// usage: node --expose-gc heap-arm.mjs <arm> <count>
// Shape everywhere: 10 state refs + 60 trivial derivations, one full read pass.
import { ref, computed } from 'vue';
import { Reactive } from './reactive-bundle.mjs';

const arm = process.argv[2];
const count = Number(process.argv[3]);

const STATE_MEMBERS = 10;
const DERIVED_MEMBERS = 60;

function buildIvueClass() {
  class $Big {}
  for (let i = 0; i < STATE_MEMBERS; i++) {
    Object.defineProperty($Big.prototype, `state${i}`, {
      configurable: true,
      get() { return ref(i); },
    });
  }
  for (let j = 0; j < DERIVED_MEMBERS; j++) {
    const source = `state${j % STATE_MEMBERS}`;
    Object.defineProperty($Big.prototype, `derived${j}`, {
      configurable: true,
      get() { return this[source].value * 2; },
    });
  }
  return Reactive($Big);
}

function makeComposable(kind) {
  return function useBig() {
    const box = {};
    for (let i = 0; i < STATE_MEMBERS; i++) box[`state${i}`] = ref(i);
    for (let j = 0; j < DERIVED_MEMBERS; j++) {
      const source = box[`state${j % STATE_MEMBERS}`];
      box[`derived${j}`] =
        kind === 'computeds'
          ? computed(() => source.value * 2)
          : () => source.value * 2;
    }
    return box;
  };
}

function gcNow() { for (let i = 0; i < 4; i++) globalThis.gc(); }

const make =
  arm === 'ivue'
    ? (() => { const Big = buildIvueClass(); return () => new Big(); })()
    : makeComposable(arm);

gcNow();
const before = process.memoryUsage().heapUsed;
const instances = new Array(count);
for (let i = 0; i < count; i++) instances[i] = make();
// one full read pass — materializes ivue's refs, touches every member
let sum = 0;
for (let i = 0; i < count; i++) {
  const instance = instances[i];
  for (let s = 0; s < STATE_MEMBERS; s++) sum += instance[`state${s}`].value;
  for (let d = 0; d < DERIVED_MEMBERS; d++) {
    const member = instance[`derived${d}`];
    sum += arm === 'ivue' ? member : arm === 'computeds' ? member.value : member();
  }
}
gcNow();
const after = process.memoryUsage().heapUsed;
const perInstance = (after - before) / count;
console.log(JSON.stringify({ arm, count, sum: sum > -1, totalMB: +((after - before) / 1048576).toFixed(1), perInstanceKB: +(perInstance / 1024).toFixed(2) }));
EOF
