async (page) => {
  await page.setViewportSize({ width: 375, height: 812 });
  const offenders = {};
  for (const path of ['', 'guide/design', 'guide/standard', 'guide/engine-under-the-idiom', 'guide/model-layer', 'guide/performance', 'guide/benchmarks', 'api/']) {
    await page.goto('http://localhost:5174/ivue/' + path, { waitUntil: 'domcontentloaded' });
    await page.waitForTimeout(1600);
    offenders[path || 'home'] = await page.evaluate(() => {
      const bad = [];
      for (const el of document.querySelectorAll('body *')) {
        const rect = el.getBoundingClientRect();
        if (rect.right > window.innerWidth + 2 && rect.width > 40) {
          const parentAlso = el.parentElement && el.parentElement.getBoundingClientRect().right > window.innerWidth + 2;
          if (!parentAlso) bad.push(`${el.tagName.toLowerCase()}.${[...el.classList].slice(0,3).join('.')} w=${Math.round(rect.width)}`);
        }
        if (bad.length > 4) break;
      }
      return bad;
    });
  }
  return offenders;
}

