  expect(entry.remountNeeded).toBe(false);

  // Behavior-only edit: method body changed, ctor/fields identical.
  class $WiredV2 {
    x = 1;
    constructor() {
      this.x = 1;
    }
    m() {
      return 'v2';
    }
  }
  Reactive($WiredV2 as any, 'hmr.test.Wired');
  expect(entry.remountNeeded).toBe(false);

  // Constructor-body edit → flagged.
  class $WiredV3 {
    x = 1;
    constructor() {
      this.x = 2;
