function regexNormalize(text) {
  return text.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/[^\n]*/g, '').replace(/\s+/g, '');
}
function scannerNormalize(text) {
  let out = ''; let i = 0; const n = text.length;
  while (i < n) {
    const ch = text[i]; const next = text[i + 1];
    if (ch === '/' && next === '/') { while (i < n && text[i] !== '\n') i++; continue; }
    if (ch === '/' && next === '*') { i += 2; while (i < n && !(text[i] === '*' && text[i+1] === '/')) i++; i += 2; continue; }
    if (ch === '"' || ch === "'" || ch === '`') {
      out += ch; i++;
      while (i < n) { const c = text[i]; out += c; i++;
        if (c === '\\') { if (i < n) { out += text[i]; i++; } continue; }
        if (c === ch) break; }
      continue;
    }
    if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') { i++; continue; }
    out += ch; i++;
  }
  return out;
}
