async (page) => {
  await page.setViewportSize({ width: 1280, height: 900 });
  await page.goto('http://localhost:5174/ivue/examples/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(3500);
  const stats = await page.evaluate(() => {
    const nums = [...document.querySelectorAll('.evs-stats .d-n')].map((el) => el.textContent.trim());
    return { total: nums[0], domRows: nums[1] };
  });
  // wheel-scroll inside the frame (lenis-driven)
  await page.locator('.evs-frame').hover();
  for (let i = 0; i < 10; i++) { await page.mouse.wheel(0, 600); await page.waitForTimeout(80); }
  await page.waitForTimeout(1200);
  const firstVisible = await page.evaluate(() => document.querySelector('.evs-row b')?.textContent);
  // jump to 50k
  await page.getByRole('button', { name: 'jump to #50,000' }).click();
  await page.waitForTimeout(2500);
  const afterJump = await page.evaluate(() => [...document.querySelectorAll('.evs-row b')].slice(0, 3).map((el) => el.textContent));
  const domAfter = await page.evaluate(() => document.querySelectorAll('.virtual-scroller__item').length);
  await page.screenshot({ path: 'tmp/screenshots/example-vscroll.png' });
  return { stats, afterWheelFirstRow: firstVisible, afterJump, domAfter };
}

